public static boolean containsAny(Collection<String> collection, String... array) {
    if (isEmpty(collection) || isEmpty(array)) {
        return false;
    } else {
        for (String str : array) {
            if (collection.contains(str)) {
                return true;
            }
        }
        return false;
    }
}

